  const content = fs.readFileSync('/tmp/postgres.log', 'utf8');
  const errorLines = content.split('\n').filter(line => line.includes('ERROR:'));
  return `Total errors found: ${errorLines.length}`;
}

async () => {
  const { execSync } = require('child_process');
  try {
    const result = execSync('grep -c "ERROR:" /tmp/postgres.log', { encoding: 'utf8' });
    return `Total errors found: ${result.trim()}`;
  } catch (error) {
    // If grep fails (no matches), return 0
    return 'Total errors found: 0';
  }
}

