#!/usr/bin/env python3

with open('/tmp/postgres.log', 'r') as f:
    content = f.read()

lines = content.split('\n')
error_count = 0

for line in lines:
    if 'ERROR:' in line:
        error_count += 1

print(f"Total errors found: {error_count}")

